// src/pages/Home.js
import React from "react";
import { Container, Row, Col } from "react-bootstrap";
import Navigation from "../components/Navigation";
import Footer from "../components/Footer";

const Home = () => {
  return (
    <div style={{ backgroundColor: "#2d2d2d", minHeight: "100vh" }}>
      {/* Dark Navbar */}
      <Navigation />

      {/* Hero Section */}
      <Container className="text-white py-5">
        <Row className="align-items-center py-5">
          {/* Left Column: Text */}
          <Col md={6} className="mb-5 mb-md-0">
            <h1 className="display-4 fw-bold">For all things money</h1>
            <p className="lead mt-4">
              Whether it's planning your savings with a new-age savings account,
              investing in mutual funds and high-interest products, or tracking
              your expenses — do it all on Fi.
            </p>

            {/* Store Badges */}
            <div className="mt-4 d-flex align-items-center">
              {/* Google Play Badge */}
              <a href="#!">
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/7/78/Google_Play_Store_badge_EN.svg"
                  alt="Get it on Google Play"
                  style={{ width: "150px", marginRight: "10px" }}
                />
              </a>

              {/* App Store Badge (Placeholder) */}
              <a href="#!">
  <img
    src="https://cdn.worldvectorlogo.com/logos/available-on-the-app-store.svg"
    alt="on the App Store"
    style={{
      width: "120px", // Increased size
      background: "#fff",
      borderRadius: "8px",
      padding: "4px",
    }}
  />
</a>

            </div>
          </Col>

          {/* Right Column: Video */}
          <Col md={6} className="text-center">
            <video
              className="img-fluid"
              style={{ maxHeight: "600px", borderRadius: "12px" }}
              autoPlay
              loop
              muted
              playsInline
            >
              <source
                src="https://dza2kd7rioahk.cloudfront.net/assets/videos/home-page_poster.webm"
                type="video/webm"
              />
              {/* Fallback text if video can't load */}
              Your browser does not support the video tag.
            </video>
          </Col>
        </Row>
      </Container>

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default Home;
